import { useState, useEffect, useRef } from "react";
import { 
  Detail, 
  ActionPanel, 
  Action, 
  showToast, 
  Toast, 
  environment,
  closeMainWindow,
  Icon,
  popToRoot,
  Clipboard,
  LocalStorage,
  LaunchProps,
  open
} from "@raycast/api";
import { exec, execFile } from "child_process";
import path from "path";
import fs from "fs";
import { translate } from 'google-translate-api-x';
import { promisify } from "util";

const execAsync = promisify(exec);
const execFileAsync = promisify(execFile);
const TEMP_IMAGE_PATH = "/tmp/raycast-ocr-temp.png";

interface OCRLaunchContext {
  recognizedText?: string;
}

export default function Command(props: LaunchProps<{ launchContext: OCRLaunchContext }>) {
  const [displayText, setDisplayText] = useState<string>("");
  const [ocrText, setOcrText] = useState<string>(""); 
  const [viewMode, setViewMode] = useState<"WELCOME" | "RESULT">("WELCOME");
  const [isLoading, setIsLoading] = useState<boolean>(true);
  
  const hasStartedRef = useRef(false);

  // Smart formatting to fix line breaks
  const smartFormat = (text: string): string => {
    return text
      .replace(/([•\-])\s/g, "\n\n$1 ")
      .replace(/(\d+\.)\s/g, "\n\n$1 ")
      .replace(/\n{3,}/g, "\n\n")
      .trim();
  };

  useEffect(() => {
    if (props.launchContext?.recognizedText) {
      handleResultMode(props.launchContext.recognizedText);
      return;
    }
    if (hasStartedRef.current) return;
    hasStartedRef.current = true;
    checkFirstRun();
  }, []);

  const handleResultMode = async (rawText: string) => {
    const formattedText = smartFormat(rawText);
    
    setOcrText(rawText);
    setDisplayText(formattedText);
    setViewMode("RESULT");
    setIsLoading(false);
    
    await Clipboard.copy(formattedText);
    showToast({ 
      style: Toast.Style.Success, 
      title: "Text Copied", 
      message: "Press Cmd+Shift+C to translate" 
    });
  };

  const checkFirstRun = async () => {
    const hasRun = await LocalStorage.getItem<boolean>("hasRunBefore");
    if (hasRun) {
      performCaptureAndOCR();
    } else {
      setIsLoading(false);
      setDisplayText(
`# 👋 Welcome to Smart OCR

### 💡 Quick Start:
1. **Capture**: Press Enter to start screen capture.
2. **Copy**: Text is automatically copied upon recognition.
3. **Translate**: Press **\`Cmd + Shift + C\`** to translate to Chinese.
`
      );
    }
  };

  const performCaptureAndOCR = async () => {
    setIsLoading(true);
    await closeMainWindow(); 

    try {
      await LocalStorage.setItem("hasRunBefore", true);
      await execAsync(`/usr/sbin/screencapture -i -x -r "${TEMP_IMAGE_PATH}"`);

      if (!fs.existsSync(TEMP_IMAGE_PATH)) {
        setIsLoading(false);
        if (viewMode === "WELCOME") await popToRoot();
        return;
      }

      await showToast({ style: Toast.Style.Animated, title: "Recognizing text..." });
      
      const scriptPath = path.join(environment.assetsPath, "ocr");
      const { stdout } = await execFileAsync(scriptPath, [TEMP_IMAGE_PATH]);
      const text = stdout.trim();
      fs.unlinkSync(TEMP_IMAGE_PATH);

      if (!text) {
        await showToast({ style: Toast.Style.Failure, title: "No text detected" });
        await popToRoot();
      } else {
        const contextData = encodeURIComponent(JSON.stringify({ recognizedText: text }));
        const deepLink = `raycast://extensions/${environment.ownerOrAuthorName}/${environment.extensionName}/capture-ocr?launchContext=${contextData}`;
        await open(deepLink);
      }

    } catch (error) {
      console.error(error);
      setIsLoading(false);
      showToast({ style: Toast.Style.Failure, title: "Error occurred" });
    }
  };

  const handleTranslate = async (targetLang: "zh-CN" | "en") => {
    const textToTranslate = displayText || ocrText; 
    if (!textToTranslate || textToTranslate.startsWith("⚠️")) return;
    
    setIsLoading(true);
    showToast({ style: Toast.Style.Animated, title: "Translating..." });

    try {
      const res = await translate(textToTranslate, { to: targetLang });
      
      setDisplayText(res.text);
      await Clipboard.copy(res.text); 
      
      showToast({ 
        style: Toast.Style.Success, 
        title: targetLang === "zh-CN" ? "Translated to Chinese" : "Translated to English", 
        message: "Copied to clipboard" 
      });
      
    } catch (error: any) {
      setIsLoading(false);
      setDisplayText(`# 😭 Translation Failed\n\nError: ${error.message}`);
      showToast({ style: Toast.Style.Failure, title: "Timeout / Network Error" });
    }
  };

  return (
    <Detail
      isLoading={isLoading}
      markdown={displayText}
      actions={
        <ActionPanel>
          {viewMode === "WELCOME" ? (
            <Action title="Start Capture" icon={Icon.Camera} onAction={performCaptureAndOCR} />
          ) : (
            <>
              <Action.CopyToClipboard title="Re-copy Text" content={displayText} />

              <ActionPanel.Section title="Translate">
                <Action
                  title="Translate to Chinese"
                  icon="🇨🇳"
                  shortcut={{ modifiers: ["cmd", "shift"], key: "c" }}
                  onAction={() => handleTranslate("zh-CN")}
                />
                <Action
                  title="Translate to English"
                  icon="🇺🇸"
                  shortcut={{ modifiers: ["cmd", "shift"], key: "e" }}
                  onAction={() => handleTranslate("en")}
                />
              </ActionPanel.Section>

              <ActionPanel.Section title="General">
                <Action 
                  title="Retake Screenshot" 
                  icon={Icon.RotateClockwise}
                  shortcut={{ modifiers: ["cmd"], key: "r" }}
                  onAction={performCaptureAndOCR} 
                />
                {viewMode === "RESULT" && (
                  <Action 
                    title="Show Original Text" 
                    icon={Icon.Document}
                    shortcut={{ modifiers: ["cmd"], key: "o" }}
                    onAction={async () => {
                      const formatted = smartFormat(ocrText);
                      setDisplayText(formatted);
                      await Clipboard.copy(formatted);
                      showToast({ title: "Original text restored" });
                    }} 
                  />
                )}
              </ActionPanel.Section>
            </>
          )}
        </ActionPanel>
      }
    />
  );
}